    public static class EnumComparerVerification
    {
        static int checks;
        static void Check(bool good, string name)
        {
            ++checks;
            if (!good)
                throw new Exception(name);
        }

        static void Field(string fieldName, string className, string enumName, int[] literals, string[] enumNames, int[] optionOrder)
        {
            Type helper = typeof(HardlightProject.HardlightEnumComparers);
            Type comparer = helper.Assembly.GetType(className, true);
            Type enumeration = helper.Assembly.GetType(enumName, true);
            FieldInfo field = helper.GetField(fieldName, BindingFlags.Public | BindingFlags.Static);
            Check(field.IsInitOnly && field.FieldType == comparer, fieldName + " exact field type/readonly");
            object value = field.GetValue(null);
            Check(value != null && value.GetType() == comparer, fieldName + " populated original comparer type");
            Check(ReferenceEquals(value, field.GetValue(null)), fieldName + " stable instance");
            Check(comparer.Assembly.GetName().Name == "HLAutoGenerated" && enumeration.Assembly.GetName().Name == "HLAutoGenerated", className + " assembly identities");
            Check(comparer.GetFields(BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance | BindingFlags.Static | BindingFlags.DeclaredOnly).Length == 0, className + " stateless");
            Check(Enum.GetUnderlyingType(enumeration) == typeof(int), enumName + " Int32");
            Type[] interfaces = comparer.GetInterfaces();
            Check(interfaces.Length == 1 && interfaces[0].GetGenericTypeDefinition() == typeof(IEqualityComparer<>) && interfaces[0].GetGenericArguments()[0] == enumeration, className + " original typed interface");
            var fields = enumeration.GetFields(BindingFlags.Public | BindingFlags.Static | BindingFlags.DeclaredOnly).OrderBy(f => f.MetadataToken).ToArray();
            Check(fields.Select(f => f.Name).SequenceEqual(enumNames), enumName + " exact declaration order");
            Check(fields.Select(f => (int)f.GetRawConstantValue()).SequenceEqual(literals), enumName + " literal values");
            var options = comparer.GetCustomAttributes<Il2CppSetOptionAttribute>().ToArray();
            Check(options.Select(a => (int)a.Option).SequenceEqual(optionOrder) && options.All(a => a.Value is bool && !(bool)a.Value), className + " original options/order");
            var eq = comparer.GetMethod("Equals", BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly);
            var hash = comparer.GetMethod("GetHashCode", BindingFlags.Public | BindingFlags.Instance | BindingFlags.DeclaredOnly);
            var values = literals.Concat(new[] { int.MinValue, int.MaxValue, -1, 0, 1, unchecked((int)0xdeadbeef) }).Distinct().ToArray();
            foreach (int a in values)
            {
                object av = Enum.ToObject(enumeration, a);
                Check((int)hash.Invoke(value, new[] { av }) == a, enumName + " signed raw hash");
                Check((bool)eq.Invoke(value, new[] { av, av }), enumName + " self equality");
            }

            foreach (int a in new[]
            {
                int.MinValue,
                int.MaxValue,
                -1,
                0,
                1,
                unchecked((int)0xdeadbeef)
            }

            )
                foreach (int b in new[]
                {
                    int.MinValue,
                    int.MaxValue,
                    -1,
                    0,
                    1,
                    unchecked((int)0xdeadbeef)
                }

                )
                    Check((bool)eq.Invoke(value, new[] { Enum.ToObject(enumeration, a), Enum.ToObject(enumeration, b) }) == (a == b), enumName + " undefined boundary equality");
            object newOne = Activator.CreateInstance(comparer);
            Check(newOne.GetType() == comparer && !ReferenceEquals(newOne, value), className + " original independent constructor");
        }

